		prefixWeight = ws.weights[0] * 0.6
		loadWeight = ws.weights[1] * 1.8
	} else {
		// Long: favor prefix-affinity (significant cache benefit)
		prefixWeight = ws.weights[0] * 2.0
		loadWeight = ws.weights[1] * 0.8
